    <dialog ref="proofDialog" class="modal admin-finance-proof-dialog"><div class="modal-head"><div><h3>{{ $t('legacy.t_849b273896de') }}</h3><small>{{ selectedRow?.proofName || selectedRow?.transactionNo }}</small></div><button type="button" class="icon-close" @click="closeProof">×</button></div><div class="finance-proof-viewer"><div v-if="proofLoading" class="admin-owner-state">{{ $t('legacy.t_38e6a8f0a0f3') }}</div><img v-else-if="proofUrl && selectedRow?.proofMimeType?.startsWith('image/')" :src="proofUrl" :alt="$t('legacy.t_849b273896de')"><iframe v-else-if="proofUrl && selectedRow?.proofMimeType === 'application/pdf'" :src="proofUrl" :title="$t('legacy.t_32540522e657')"></iframe><div v-else class="admin-owner-state">{{ proofError || $t('legacy.t_410b7e2a33ff') }}</div></div><menu><button @click="closeProof">{{ $t('legacy.t_ddc05404b0d6') }}</button><button class="primary-btn" :disabled="!selectedRow?.proofDocumentId" @click="downloadProof">{{ $t('legacy.t_fb332e3c9ee6') }}</button></menu></dialog>
  </section>
</template>

<script>
import { batchConfirmAdminFinanceReviews, batchReopenAdminFinanceReviews, confirmAdminFinanceReview, downloadAdminFinanceDocuments, fetchAdminFinanceProjects, fetchAdminFinanceReviews, fetchAdminReserveProof, getAdminFinanceDocumentUrl, rejectAdminFinanceReview, reopenAdminFinanceReview } from '../services/propertyApi';
import FinanceAllocationNoteEditor from './FinanceAllocationNoteEditor.vue';
import { formatDate, formatDateTime, todayIsoDate } from '../utils/dateFormat';

export default {
  components: { FinanceAllocationNoteEditor },
  inject: ['page'],
  data() { return { rows: [], selectedId: null, selectedIds: [], pageNumber: 1, pageSize: 10, totalRows: 0, totalPages: 1, loading: false, errorMessage: '', serial: 0, approving: true, decisionDate: todayIsoDate(), batchDate: todayIsoDate(), today: todayIsoDate(), decisionNote: '', batchNote: '充值资料与银行入账信息核对一致', reopenNote: '', batchReopenNote: '', actionSaving: false, actionError: '', batchBusy: false, proofLoading: false, proofError: '', proofUrl: '' }; },
  computed: {
    selectedRow() { return this.rows.find(row => row.id === this.selectedId) || this.rows[0] || null; },
    viewMode() { return this.page.adminFinanceViewMode === 'history' ? 'history' : 'pending'; },
    pendingRows() { return this.rows.filter(row => row.confirmationStatus === 'pending'); },
    selectableRows() { return this.viewMode === 'history' ? this.rows : this.pendingRows; },
    batchRows() { return this.rows.filter(row => this.selectedIds.includes(row.id)); },
    batchTotal() { return this.batchRows.reduce((sum, row) => sum + Number(row.amount || 0), 0); },
    allSelectableSelected() { return this.selectableRows.length > 0 && this.selectableRows.every(row => this.selectedIds.includes(row.id)); },
    selectedReopenIds() { return this.rows.filter(row => this.selectedIds.includes(row.id) && row.confirmationStatus === 'confirmed').map(row => row.id); },
    visiblePages() { const start = Math.max(1, Math.min(this.pageNumber - 2, this.totalPages - 4)); return Array.from({ length: Math.min(5, this.totalPages) }, (_, i) => start + i); },
    batchNonce() { return this.page.adminFinanceBatchNonce; }, refreshNonce() { return this.page.adminFinanceRefreshNonce; }
  },
  watch: {
    'page.moduleSearch'() { this.resetLoad(); }, 'page.globalSearch'() { this.resetLoad(); }, 'page.projectFilter'() { this.resetLoad(); }, 'page.statusFilter'() { this.resetLoad(); }, 'page.adminFinanceViewMode'() { this.resetLoad(); }, 'page.dateStart'() { this.resetLoad(); }, 'page.dateEnd'() { this.resetLoad(); }, pageSize() { this.resetLoad(); },
    batchNonce(v, old) { if (v > old) this.openBatch(); }, refreshNonce(v, old) { if (v > old) this.loadData(); },
    rows: { deep: true, handler(rows) { if (!rows.some(row => row.id === this.selectedId)) this.selectedId = rows[0]?.id || null; } }
  },
  mounted() { this.loadData(); }, beforeUnmount() { this.revokeProof(); },
  methods: {
    async loadData() { const serial = ++this.serial; this.loading = true; this.errorMessage = ''; try { const params = { type: 'reserve', page: this.pageNumber, pageSize: this.pageSize, keyword: this.page.globalSearch || this.page.moduleSearch || '', projectName: String(this.page.projectFilter || '').includes('全部') ? '' : this.page.projectFilter, status: this.requestStatus(), startDate: this.page.dateStart, endDate: this.page.dateEnd }; const [response, projects] = await Promise.all([fetchAdminFinanceReviews(params), fetchAdminFinanceProjects('reserve')]); if (serial !== this.serial) return; this.rows = response.rows || []; this.totalRows = response.page?.totalRows || 0; this.totalPages = response.page?.totalPages || 1; this.pageNumber = response.page?.page || 1; this.page.adminFinanceProjects = projects || []; this.page.adminFinanceMetrics = this.metrics(response.summary || {}); this.selectedIds = this.selectedIds.filter(id => this.rows.some(row => row.id === id)); } catch (error) { if (serial !== this.serial) return; this.rows = []; this.errorMessage = error.message || 'API request failed'; this.page.adminFinanceMetrics = null; } finally { if (serial === this.serial) this.loading = false; } },
    metrics(s) { return [{ label: '待確認充值', value: `${Number(s.pendingCount || 0)} 筆`, delta: `RM ${this.money(s.pendingAmount)}`, trend: Number(s.pendingCount) ? 'down' : 'up' }, { label: '已確認充值', value: `${Number(s.confirmedCount || 0)} 筆`, delta: '已增加預備金', trend: 'up' }, { label: '已退回申請', value: `${Number(s.rejectedCount || 0)} 筆`, delta: '保留退回原因', trend: Number(s.rejectedCount) ? 'down' : 'up' }, { label: '待同步 SQL', value: `${Number(s.pendingSyncCount || 0)} 筆`, delta: '會計同步狀態', trend: Number(s.pendingSyncCount) ? 'down' : 'up' }, { label: '本月確認充值', value: `RM ${this.money(s.confirmedMonthAmount)}`, delta: '本月實際入賬', trend: 'up' }]; },
    resetLoad() { this.pageNumber = 1; this.selectedIds = []; this.loadData(); }, goPage(n) { if (n >= 1 && n <= this.totalPages && n !== this.pageNumber) { this.pageNumber = n; this.loadData(); } }, selectRow(row) { this.selectedId = row.id; }, openDetails(row) { this.selectRow(row); this.$nextTick(() => this.$refs.detailDialog?.showModal()); }, closeDetails() { this.$refs.detailDialog?.close(); }, openProofFromDetails() { this.closeDetails(); this.$nextTick(this.openProof); }, openDecisionFromDetails(approved) { this.closeDetails(); this.$nextTick(() => this.openDecision(approved)); }, openReopenFromDetails() { this.closeDetails(); this.$nextTick(this.openReopen); }, documentUrl(row, type) { return row?.id ? getAdminFinanceDocumentUrl(row.id, type) : '#'; }, async batchDownload(type) { const ids = [...this.selectedIds]; if (!ids.length) { this.page.showToast('请先勾选需要下载的历史记录'); return; } this.batchBusy = true; try { const result = await downloadAdminFinanceDocuments(ids, type); const url = URL.createObjectURL(result.blob); const link = document.createElement('a'); link.href = url; link.download = result.filename; document.body.appendChild(link); link.click(); link.remove(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); this.page.showToast(`已生成 ${ids.length} 份${type === 'invoice' ? '发票' : '收据'}`); } catch (error) { this.page.showToast(error.message || '批量下载失败'); } finally { this.batchBusy = false; } },
    toggleSelectablePage(event) { const ids = this.selectableRows.map(row => row.id); this.selectedIds = event.target.checked ? [...new Set([...this.selectedIds, ...ids])] : this.selectedIds.filter(id => !ids.includes(id)); },
    openDecision(approved) { this.approving = approved; this.decisionDate = todayIsoDate(); this.decisionNote = approved ? '充值资料与银行入账信息核对一致' : ''; this.actionError = ''; this.$refs.decisionDialog?.showModal(); }, closeDecision() { this.$refs.decisionDialog?.close(); },
    async submitDecision() { if (!this.decisionNote || (this.approving && !this.decisionDate)) { this.actionError = '請填寫審核資料'; return; } this.actionSaving = true; this.actionError = ''; try { if (this.approving) await confirmAdminFinanceReview(this.selectedRow.id, this.decisionDate, this.decisionNote); else await rejectAdminFinanceReview(this.selectedRow.id, this.decisionNote); this.closeDecision(); await this.loadData(); this.page.showToast(this.approving ? '預備金充值已確認並入賬' : '充值申請已退回'); } catch (error) { this.actionError = error.message || '充值審核失敗'; } finally { this.actionSaving = false; } },
    openRowReopen(row) { this.selectRow(row); this.$nextTick(this.openReopen); }, openReopen() { this.reopenNote = ''; this.actionError = ''; this.$refs.reopenDialog?.showModal(); }, closeReopen() { this.$refs.reopenDialog?.close(); }, async submitReopen() { if (!this.reopenNote) { this.actionError = this.$t('finance.reviewNoteRequired'); return; } this.actionSaving = true; this.actionError = ''; try { await reopenAdminFinanceReview(this.selectedRow.id, this.reopenNote); this.closeReopen(); await this.loadData(); this.page.showToast(this.$t('finance.reopenSuccess')); } catch (error) { this.actionError = error.message || this.$t('finance.reopenFailed'); } finally { this.actionSaving = false; } },
    openBatchReopen() { if (!this.selectedReopenIds.length) { this.page.showToast('请先勾选已确认充值'); return; } this.batchReopenNote = ''; this.actionError = ''; this.$refs.batchReopenDialog?.showModal(); }, closeBatchReopen() { this.$refs.batchReopenDialog?.close(); }, async submitBatchReopen() { if (!this.batchReopenNote) { this.actionError = '请填写退回原因'; return; } const ids = [...this.selectedReopenIds]; this.actionSaving = true; this.actionError = ''; try { await batchReopenAdminFinanceReviews(ids, this.batchReopenNote); this.closeBatchReopen(); this.selectedIds = []; await this.loadData(); this.page.showToast(`已批量退回 ${ids.length} 笔充值`); } catch (error) { this.actionError = error.message || '批量退回失败'; } finally { this.actionSaving = false; } },
    openBatch() { if (!this.selectedIds.length) this.selectedIds = this.pendingRows.map(row => row.id); if (!this.selectedIds.length) { this.page.showToast('当前列表没有可确认充值'); return; } this.batchDate = todayIsoDate(); this.actionError = ''; this.$refs.batchDialog?.showModal(); }, closeBatch() { this.$refs.batchDialog?.close(); }, async submitBatch() { if (!this.batchNote || !this.batchDate) return; this.actionSaving = true; this.actionError = ''; const count = this.selectedIds.length; try { await batchConfirmAdminFinanceReviews(this.selectedIds, this.batchDate, this.batchNote); this.closeBatch(); this.selectedIds = []; await this.loadData(); this.page.showToast(`已確認 ${count} 筆預備金充值`); } catch (error) { this.actionError = error.message || '批量確認失敗'; } finally { this.actionSaving = false; } },
    selectAndOpenProof(row) { this.selectRow(row); this.$nextTick(this.openProof); }, async openProof() { if (!this.selectedRow?.proofDocumentId) return; this.revokeProof(); this.proofLoading = true; this.proofError = ''; this.$refs.proofDialog?.showModal(); try { const result = await fetchAdminReserveProof(this.selectedRow.proofDocumentId); this.proofUrl = URL.createObjectURL(result.blob); } catch (error) { this.proofError = error.message || '憑證載入失敗'; } finally { this.proofLoading = false; } }, closeProof() { this.$refs.proofDialog?.close(); this.revokeProof(); }, revokeProof() { if (this.proofUrl) URL.revokeObjectURL(this.proofUrl); this.proofUrl = ''; }, async downloadProof() { try { const result = await fetchAdminReserveProof(this.selectedRow.proofDocumentId, true); const url = URL.createObjectURL(result.blob); const link = document.createElement('a'); link.href = url; link.download = this.selectedRow.proofName || `reserve-proof-${this.selectedRow.id}`; link.click(); URL.revokeObjectURL(url); } catch (error) { this.page.showToast(error.message || '憑證下載失敗'); } },
    statusParam(v) { return ({ '待確認': 'pending', '已確認': 'confirmed', '已退回': 'rejected', '待同步': 'sync_pending', '同步失敗': 'sync_failed' })[v] || ''; }, requestStatus() { if (this.viewMode === 'pending') return 'pending'; return this.statusParam(this.page.statusFilter) || 'history'; }, confirmationLabel(v) { return ({ pending: '待確認', confirmed: '已確認', rejected: '已退回' })[v] || '未知'; }, confirmationClass(v) { return v === 'confirmed' ? 'green' : v === 'rejected' ? 'red' : 'orange'; }, syncLabel(v) { return ({ not_synced: '未同步', pending: '待同步', synced: '已同步', failed: '同步失敗' })[v] || '未同步'; }, syncClass(v) { return v === 'synced' ? 'green' : v === 'failed' ? 'red' : 'orange'; }, paymentMethodLabel(v) { return ({ bank_transfer: '銀行轉賬', online_payment: '線上支付' })[v] || v || '—'; }, displayDate(v) { return formatDate(v); }, dateTime(v) { return formatDateTime(v); }, money(v) { return Number(v || 0).toLocaleString('en-MY', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
  }
};
